// GroupByParam groups by the given page parameter key's value and with the given order.
// Valid values for order is asc, desc, rev and reverse.
func (p Pages) GroupByParam(key string, order ...string) (PagesGroup, error) {
	c := newPageCatalog(p)
	c.groupKey = key
	return c.groupByParam(order...)
}

func (c *pageCatalog) groupByParam(order ...string) (PagesGroup, error) {
	if len(c.groupedPages) < 1 || c.groupKey == "" {
		if len(c.groupedPages) < 1 {
			return nil, nil
		}
	}

	c.resolveGroupOrder(order)

	var tmp reflect.Value
	var keyt reflect.Type
	for _, e := range c.groupedPages {
		param := c.pageParam(e, true)
		if param != nil {
			if _, ok := param.([]string); !ok {
				keyt = reflect.TypeOf(param)
				tmp = reflect.MakeMap(reflect.MapOf(keyt, pagesType))
				break
			}
		}
	}
	if !tmp.IsValid() {
		return nil, errors.New("there is no such param")
	}

	c.fillParamBuckets(keyt, tmp)
	return c.groupsFromMap(tmp), nil
}

func (c *pageCatalog) fillParamBuckets(keyt reflect.Type, tmp reflect.Value) {
	c.paramIndex = make(map[any]Pages)
	for _, e := range c.groupedPages {
		param := c.pageParam(e, false)
		if param == nil || reflect.TypeOf(param) != keyt {
			continue
		}
		c.paramIndex[param] = append(c.paramIndex[param], e)
		v := reflect.ValueOf(param)
		if !tmp.MapIndex(v).IsValid() {
			tmp.SetMapIndex(v, reflect.MakeSlice(pagesType, 0, 0))
		}
		tmp.SetMapIndex(v, reflect.Append(tmp.MapIndex(v), reflect.ValueOf(e)))
	}
}

func (p Pages) groupByDateField(format string, sorter func(p Pages) Pages, getDate func(p Page) time.Time, order ...string) (PagesGroup, error) {
	c := newPageCatalog(p)
	return c.groupByDateField(format, sorter, getDate, order...)
}

func (c *pageCatalog) groupByDateField(format string, sorter func(p Pages) Pages, getDate func(p Page) time.Time, order ...string) (PagesGroup, error) {
	if len(c.groupedPages) < 1 {
		return nil, nil
	}

	sp := sorter(c.groupedPages)
	if c.wantsReverseDateGroups(order) {
		sp = sp.Reverse()
	}

	if sp == nil {
		return nil, nil
	}

	firstPage := sp[0]
	date := getDate(firstPage)

	// Pages may be a mix of multiple languages, so we need to use the language
	// for the currently rendered Site.
	currentSite := firstPage.Site().Current()
	formatter := langs.GetTimeFormatter(currentSite.Language())
	formatted := formatter.Format(date, format)
	c.dateBuckets = PagesGroup{PageGroup{Key: formatted, Pages: make(Pages, 0)}}
	c.dateBuckets[0].Pages = append(c.dateBuckets[0].Pages, sp[0])

	i := 0
	for _, e := range sp[1:] {
		date = getDate(e)
		formatted := formatter.Format(date, format)
		if c.dateBuckets[i].Key.(string) != formatted {
			c.dateBuckets = append(c.dateBuckets, PageGroup{Key: formatted})
			i++
		}
		c.dateBuckets[i].Pages = append(c.dateBuckets[i].Pages, e)
	}
	return c.dateBuckets, nil
}

